using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class AudioWorkspaceOperations
{
    public void linked_drums_dialog(Control o)
    {
        var clip=Session(o).Call("primary_clip").AsGodotObject();var actor=Session(o).Call("primary_actor").AsGodotObject();
        if(clip==null||actor==null||!Dict(actor,"values").ContainsKey(new StringName("drum_instances"))){notice(o,"Select a generated drum part. Linked drums retain reusable definitions and per-bar instances. Free piano/step edits detach that part to notes, with Undo.");return;}
        string clipId=clip.Get("id").AsString();if(!Session(o).Call("can_edit",clipId).AsBool()){notice(o,"Unlock the drum part first.");return;}
        var owner=Session(o);var document=Document(o);var dialog=window(o,"Linked drum patterns",new Vector2I(920,610));var host=dialog["host"].As<Node>();var windowNode=dialog["window"].As<Window>();
        label(host,"Edit a pattern once to update every linked instance. Make unique disconnects only the chosen instance. Free note editing detaches the entire part; Undo restores links.");
        var chooser=new OptionButton();host.AddChild(chooser);foreach(var raw in Get(Dict(actor,"values"),"drum_instances",new GArray()).AsGodotArray()){var instance=raw.AsGodotDictionary();string id=instance["pattern_id"].AsString();chooser.AddItem("Beat "+instance["start"].AsDouble().ToString("F2",System.Globalization.CultureInfo.InvariantCulture)+" · pattern "+ScalarPrefix(id,6));chooser.SetItemMetadata(chooser.ItemCount-1,instance["id"]);}
        var scroll=new ScrollContainer{SizeFlagsVertical=Control.SizeFlags.ExpandFill};host.AddChild(scroll);var editor=new VBoxContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};scroll.AddChild(editor);
        Settings Resolve(){if(Session(o)!=owner||Document(o)!=document||owner.Get("_before").VariantType!=Variant.Type.Nil||!owner.Call("can_edit",clipId).AsBool()||chooser.Selected<0)return new Settings();var current=document.Call("actor_for_clip",clipId).AsGodotObject();if(current==null)return new Settings();var values=Dict(current,"values");foreach(var raw in Get(values,"drum_instances",new GArray()).AsGodotArray()){var instance=raw.AsGodotDictionary();if(instance["id"].AsString()==chooser.GetSelectedMetadata().AsString())return new Settings{["actor"]=current,["instance"]=instance,["pattern"]=Get(Get(values,"drum_patterns",new Settings()).AsGodotDictionary(),instance["pattern_id"].AsString(),new Settings())};}return new Settings();}
        void Mark(Settings target){using var linked=new AudioLinkedPatternOperations();var current=target["actor"].AsGodotObject();linked.sync(current);Dict(current,"values")[new StringName("notes_dirty")]=true;}
        void Refresh(){clear(editor);var target=Resolve();if(target.Count==0||target["pattern"].AsGodotDictionary().Count==0){label(editor,"This instance changed. Reopen Linked drums.");return;}var pattern=target["pattern"].AsGodotDictionary();var instance=target["instance"].AsGodotDictionary();NumberAction(o,editor,"Instance beat",instance["start"].AsDouble(),0,2048,.25,value=>{var current=Resolve();if(current.Count==0)return;SessionAction(o,"Move linked drum instance",()=>{current["instance"].AsGodotDictionary()["start"]=value;Mark(current);});render_dirty_notes(o);});var lanes=Get(pattern,"lanes",new GArray()).AsGodotArray();for(int laneIndex=0;laneIndex<lanes.Count;laneIndex++){int laneSlot=laneIndex;var lane=lanes[laneIndex].AsGodotDictionary();var row=new HFlowContainer();editor.AddChild(row);label(row,"MIDI "+Get(lane,"pitch",36).AsInt32());var cells=Get(lane,"values",new GArray()).AsGodotArray();for(int cellIndex=0;cellIndex<Math.Min(64,cells.Count);cellIndex++){int cellSlot=cellIndex;var cell=cells[cellIndex];bool enabled=cell.VariantType==Variant.Type.Dictionary?Get(cell.AsGodotDictionary(),"enabled",true).AsBool()&&Get(cell.AsGodotDictionary(),"velocity",0).AsDouble()>0:cell.AsDouble()>0;var toggle=new CheckButton{Text=(cellIndex+1).ToString(),ButtonPressed=enabled};row.AddChild(toggle);toggle.Toggled+=active=>{var current=Resolve();if(current.Count==0)return;var currentLanes=Get(current["pattern"].AsGodotDictionary(),"lanes",new GArray()).AsGodotArray();if(laneSlot>=currentLanes.Count)return;var currentCells=Get(currentLanes[laneSlot].AsGodotDictionary(),"values",new GArray()).AsGodotArray();if(cellSlot>=currentCells.Count)return;SessionAction(o,"Edit linked drum step",()=>{var value=currentCells[cellSlot];if(value.VariantType==Variant.Type.Dictionary){var data=value.AsGodotDictionary();data["enabled"]=active;if(active&&Get(data,"velocity",0).AsDouble()<=0)data["velocity"]=.8;}else currentCells[cellSlot]=active?.8:0;Mark(current);});render_dirty_notes(o);};}}}
        var actions=new HFlowContainer();host.AddChild(actions);
        ActionButton(actions,"Make selected instance unique",()=>{var target=Resolve();if(target.Count==0)return;var values=Dict(target["actor"].AsGodotObject(),"values");var patterns=Get(values,"drum_patterns",new Settings()).AsGodotDictionary();if(patterns.Count>=256){notice(o,"The linked definition limit is 256. Detach or remove unused definitions first.");return;}SessionAction(o,"Unlink drum instance",()=>{string id=NewAudioId();patterns[id]=target["pattern"].AsGodotDictionary().Duplicate(true);target["instance"].AsGodotDictionary()["pattern_id"]=id;values[new StringName("notes_dirty")]=true;});windowNode.QueueFree();linked_drums_dialog(o);render_dirty_notes(o);});
        ActionButton(actions,"Duplicate linked instance",()=>{var target=Resolve();if(target.Count==0)return;var values=Dict(target["actor"].AsGodotObject(),"values");var instances=Get(values,"drum_instances",new GArray()).AsGodotArray();var proposed=instances.Duplicate(true);var added=target["instance"].AsGodotDictionary().Duplicate(true);added["id"]=NewAudioId();added["start"]=added["start"].AsDouble()+added["length"].AsDouble();proposed.Add(added);using var linked=new AudioLinkedPatternOperations();string problem=linked.validate(Get(values,"drum_patterns",new Settings()),proposed);if(problem.Length>0){notice(o,problem);return;}SessionAction(o,"Duplicate linked drum instance",()=>{instances.Add(added);values[new StringName("pattern_beats")]=Math.Max(Get(values,"pattern_beats",4).AsDouble(),added["start"].AsDouble()+added["length"].AsDouble());Mark(target);});windowNode.QueueFree();linked_drums_dialog(o);render_dirty_notes(o);});
        ActionButton(actions,"Detach part to editable notes",()=>{var target=Resolve();if(target.Count==0)return;SessionAction(o,"Detach linked drums",()=>{using var linked=new AudioLinkedPatternOperations();linked.detach(target["actor"].AsGodotObject());});windowNode.QueueFree();});chooser.ItemSelected+=_=>Refresh();Refresh();
    }
}
